/*
 * CS:APP Practice Problem 3.67
 *
 * Examine the code generated by gcc for functions that have structures
 * as arguments and return values.
 */

#include <stdio.h>

typedef struct {
    long a[2];
    long *p;
} strA;

typedef struct {
    long u[2];
    long q;
} strB;

strB process(strA s) {
    strB r;
    r.u[0] = s.a[1];
    r.u[1] = s.a[0];
    r.q = *s.p;
    return r;
}

long eval(long x, long y, long z) {
    strA s;
    s.a[0] = x;
    s.a[1] = y;
    s.p = &z;
    strB r = process(s);
    return r.u[0] + r.u[1] + r.q;
}

/*
Assembly generated by GCC:

%rdi = implicit return pointer to strB r, passed
by the caller. Basically, the user allocates
sizeof(strB) bytes on their own stack frame,
exclusively for that specific struct,
and passes the pointer in %rdi to that
allocated struct.

The offsets here basically are:

8(%rsp) = &s (struct strA *):
[ 24(%rsp) long *p   ]
[ 16(%rsp) long a[1] ]
[  8(%rsp) long a[0] ]

%rdi = &r (struct strB *)
[ 16(%rdi) long q    ]
[  8(%rdi) long u[1] ]
[  0(%rdi) long u[0] ]

process:
    movq    %rdi, %rax     ; return &r
    movq    24(%rsp), %rdx ; get the pointer s.p
    movq    (%rdx), %rdx   ; dereference *s.p
    movq    16(%rsp), %rcx ; get a[1]
    movq    %rcx, (%rdi)   ; u[0] = a[1]
    movq    8(%rsp), %rcx  ; get a[0]
    movq    %rcx, 8(%rdi)  ; u[1] = a[0]
    movq    %rdx, 16(%rdi) ; r.q = *s.p
    ret

; long eval(long x, long y, long z)
; x in %rdi, y in %rsi, z in %rdx
eval:
    subq    $104, %rsp
    movq    %rdx, 24(%rsp)
    leaq    24(%rsp), %rax
    movq    %rdi, (%rsp)
    movq    %rsi, 8(%rsp)
    movq    %rax, 16(%rsp)
    leaq    64(%rsp), %rdi
    call    process
    movq    72(%rsp), %rax
    addq    64(%rsp), %rax
    addq    80(%rsp), %rax
    addq    $104, %rsp
    ret

Questions:

A. We can see on line 2 of function eval that it allocates 104 bytes on the stack.
   Diagram the stack frame for eval, showing the values that it stores on the
   stack prior to calling process.

B. What value does eval pass in its call to process?

C. How does the code for process access the elements of structure argument s?

D. How does the code for process set the fields of result structure r?

E. Complete your diagram of the stack frame for eval, showing how eval
   accesses the elements of structure r following the return from process.

F. What general principles can you discern about how structure values are
   passed as function arguments and how they are returned as function results?
*/

/* 
Answers:

A. Here is the stack frame for eval (each section has a quad-word):

[  ??   ??  ] <- 96(%rsp)
[  ??   ??  ] <- 88(%rsp)
[  ??   ??  ] <- 80(%rsp)
[  ??   ??  ] <- 72(%rsp)
[ ?? ] <- 64(%rsp) ((struct strB *)&r, passed in %rdi)
[ ?? ] <- 56(%rsp)
[ ?? ] <- 48(%rsp)
[ ?? ] <- 40(%rsp)
[ ?? ] <- 32(%rsp)
[ z  ] <- 24(%rsp)
[ &z ] <- 16(%rsp)
[ y  ] <-  8(%rsp)
[ x  ] <-  0(%rsp)

B. The value passed by eval to process is the pointer to
   the r, because the struct is larger than 16 bytes,
   and by the ABI, it's classified as MEMORY:

"2. If the type has class MEMORY, then the caller 
provides space for the return value
and passes the address of this storage in 
%rdi as if it were the first argument to the
function. In effect, this address becomes a 
“hidden” first argument. This storage
must not overlap any data visible to the 
callee through other names than this argu-
ment."


C. How does the code for process access the elements of structure argument s?

Directly from the stack pointer, relative to its stack frame.
So it starts from 8(%rsp) because the return address was pushed.

D. How does the code for process set the fields of result structure r?

It accesses each quadword of the structures relative to its 
stack frame and stores them in the hidden result pointer passed
by the caller.

E. Complete your diagram of the stack frame for eval, showing how eval
   accesses the elements of structure r following the return from process.

[ ?? ] <- 96(%rsp)
[  z ] <- 88(%rsp)
[  x ] <- 80(%rsp)
[  y ] <- 72(%rsp) ((struct strB *)&r, passed in %rdi)
[ ?? ] <- 64(%rsp) 
[ ?? ] <- 56(%rsp)
[ ?? ] <- 48(%rsp)
[ ?? ] <- 40(%rsp)
[ z  ] <- 32(%rsp)
[ &z ] <- 24(%rsp)
[ y  ]  <- 16(%rsp)
[ x  ]  <-  8(%rsp)
[ ret ]  <-  0(%rsp)

F. What general principles can you discern about how structure values are
   passed as function arguments and how they are returned as function results?

Yea so, the way the structures are passed under the System V AMD64 ABI, is that
if a struct is passed by value to a function, and it is larger than 16 bytes,
it is considered of class MEMORY, and it is accessed directly from the relative
stack frame. For a return struct by value of a function, the caller allocates
memory for that struct, and passes a hidden pointer in %rdi to that memory.
The callee can then write to it from that pointer.
*/
